PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE commerce_business_profiles (
  id TEXT PRIMARY KEY CHECK (id = 'primary'),
  trading_name TEXT NOT NULL CHECK (length(trading_name) BETWEEN 1 AND 160),
  legal_business_name_ciphertext TEXT,
  country_code TEXT NOT NULL DEFAULT 'CA' CHECK (length(country_code) = 2),
  province_code TEXT NOT NULL DEFAULT 'ON' CHECK (length(province_code) BETWEEN 2 AND 3),
  currency_code TEXT NOT NULL DEFAULT 'CAD' CHECK (length(currency_code) = 3),
  public_address_json TEXT,
  private_address_ciphertext TEXT,
  public_contact_email TEXT,
  support_email TEXT,
  public_phone TEXT,
  website_url TEXT,
  invoice_prefix TEXT,
  document_footer TEXT,
  tax_provider_state TEXT NOT NULL DEFAULT 'unavailable' CHECK (tax_provider_state IN ('unavailable', 'setup_required', 'pending', 'disabled')),
  invoice_accent_color TEXT NOT NULL DEFAULT '#f3c928' CHECK (length(invoice_accent_color) = 7),
  receipt_accent_color TEXT NOT NULL DEFAULT '#f3c928' CHECK (length(receipt_accent_color) = 7),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
, private_phone_ciphertext TEXT, business_registration_number_ciphertext TEXT);
CREATE TABLE commerce_provider_connections (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL UNIQUE CHECK (provider IN ('stripe', 'printful', 'paypal', 'printify', 'wix')),
  integration_mode TEXT CHECK (integration_mode IS NULL OR integration_mode IN ('direct_merchant', 'fulfillment', 'legacy')),
  credential_custody TEXT NOT NULL CHECK (credential_custody IN ('environment_secret', 'admin_encrypted', 'no_secret')),
  credential_ciphertext TEXT,
  status TEXT NOT NULL CHECK (status IN ('unavailable', 'setup_required', 'pending', 'connected', 'restricted', 'disabled', 'error', 'legacy_production', 'deferred')),
  environment TEXT NOT NULL CHECK (environment IN ('staging', 'test', 'live', 'legacy', 'deferred')),
  external_account_id TEXT,
  country_code TEXT,
  currency_code TEXT,
  safe_metadata_json TEXT NOT NULL DEFAULT '{}',
  last_synchronized_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK (credential_ciphertext IS NULL OR credential_custody = 'admin_encrypted'),
  CHECK (provider <> 'stripe' OR integration_mode = 'direct_merchant'),
  CHECK (provider <> 'stripe' OR credential_custody = 'environment_secret')
);
CREATE TABLE commerce_settings (
  setting_key TEXT PRIMARY KEY,
  value_json TEXT NOT NULL,
  classification TEXT NOT NULL DEFAULT 'safe' CHECK (classification IN ('safe', 'private_encrypted')),
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
);
CREATE TABLE commerce_permission_grants (
  id TEXT PRIMARY KEY,
  account_id TEXT NOT NULL,
  capability TEXT NOT NULL CHECK (capability IN ('commerce.view', 'commerce.business.manage', 'commerce.payments.manage', 'commerce.integrations.manage', 'commerce.templates.manage')),
  granted_by_account_id TEXT NOT NULL,
  granted_at TEXT NOT NULL,
  revoked_by_account_id TEXT,
  revoked_at TEXT,
  reason TEXT,
  CHECK ((revoked_at IS NULL AND revoked_by_account_id IS NULL) OR (revoked_at IS NOT NULL AND revoked_by_account_id IS NOT NULL))
);
CREATE TABLE commerce_products (
  id TEXT PRIMARY KEY,
  source_provider TEXT NOT NULL CHECK (source_provider IN ('wix_snapshot', 'printful', 'printify', 'manual')),
  external_product_id TEXT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  currency_code TEXT NOT NULL DEFAULT 'CAD' CHECK (length(currency_code) = 3),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'restricted', 'disabled', 'error', 'legacy_production')),
  safe_metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, is_featured INTEGER NOT NULL DEFAULT 0 CHECK (is_featured IN (0, 1)), featured_order INTEGER CHECK (featured_order IS NULL OR featured_order BETWEEN 0 AND 9999), unit_amount INTEGER CHECK (unit_amount IS NULL OR unit_amount BETWEEN 1 AND 100000000), checkout_environment TEXT NOT NULL DEFAULT 'test' CHECK (checkout_environment IN ('test', 'live')), visibility TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private', 'public')), max_checkout_quantity INTEGER NOT NULL DEFAULT 20 CHECK (max_checkout_quantity BETWEEN 1 AND 20), requires_shipping INTEGER NOT NULL DEFAULT 0 CHECK (requires_shipping IN (0, 1)), target_printful_product_id TEXT
  CHECK (target_printful_product_id IS NULL OR length(target_printful_product_id) BETWEEN 1 AND 240), target_printful_external_id TEXT
  CHECK (target_printful_external_id IS NULL OR length(target_printful_external_id) BETWEEN 1 AND 240), legacy_printful_source_product_id TEXT
  CHECK (legacy_printful_source_product_id IS NULL OR length(legacy_printful_source_product_id) BETWEEN 1 AND 240), legacy_wix_external_product_id TEXT
  CHECK (legacy_wix_external_product_id IS NULL OR length(legacy_wix_external_product_id) BETWEEN 1 AND 240), migration_status TEXT NOT NULL DEFAULT 'not_started'
  CHECK (migration_status IN ('not_started', 'selected', 'resolving_files', 'target_created', 'provider_processing', 'target_verified', 'blocked', 'manual_review', 'excluded', 'target_native')), migration_provenance_json TEXT NOT NULL DEFAULT '{}'
  CHECK (json_valid(migration_provenance_json) AND json_type(migration_provenance_json) = 'object' AND length(migration_provenance_json) <= 16384),
  UNIQUE (source_provider, external_product_id)
);
CREATE TABLE commerce_orders (
  id TEXT PRIMARY KEY,
  customer_payment_provider TEXT NOT NULL DEFAULT 'stripe' CHECK (customer_payment_provider IN ('stripe', 'paypal', 'wix_legacy')),
  payment_status TEXT NOT NULL DEFAULT 'pending' CHECK (payment_status IN ('pending', 'paid', 'refunded', 'partially_refunded', 'disputed', 'failed', 'canceled')),
  fulfillment_provider TEXT CHECK (fulfillment_provider IN ('printful', 'printify', 'manual', 'wix_legacy')),
  fulfillment_status TEXT NOT NULL DEFAULT 'disabled' CHECK (fulfillment_status IN ('disabled', 'pending', 'draft', 'submitted', 'fulfilled', 'canceled', 'error')),
  currency_code TEXT NOT NULL DEFAULT 'CAD' CHECK (length(currency_code) = 3),
  customer_gross_amount INTEGER NOT NULL DEFAULT 0 CHECK (customer_gross_amount >= 0),
  stripe_fee_amount INTEGER NOT NULL DEFAULT 0 CHECK (stripe_fee_amount >= 0),
  refund_amount INTEGER NOT NULL DEFAULT 0 CHECK (refund_amount >= 0),
  printful_product_cost_amount INTEGER NOT NULL DEFAULT 0 CHECK (printful_product_cost_amount >= 0),
  printful_shipping_cost_amount INTEGER NOT NULL DEFAULT 0 CHECK (printful_shipping_cost_amount >= 0),
  printful_tax_amount INTEGER NOT NULL DEFAULT 0 CHECK (printful_tax_amount >= 0),
  printful_refund_credit_amount INTEGER NOT NULL DEFAULT 0 CHECK (printful_refund_credit_amount >= 0),
  gross_margin_amount INTEGER NOT NULL DEFAULT 0,
  stripe_checkout_session_id TEXT UNIQUE,
  printful_order_id TEXT UNIQUE,
  safe_metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, checkout_request_id TEXT CHECK (checkout_request_id IS NULL OR length(checkout_request_id) = 36), checkout_request_digest TEXT CHECK (checkout_request_digest IS NULL OR (length(checkout_request_digest) = 64 AND checkout_request_digest NOT GLOB '*[^0-9a-f]*')), cart_digest TEXT CHECK (cart_digest IS NULL OR (length(cart_digest) = 64 AND cart_digest NOT GLOB '*[^0-9a-f]*')), environment TEXT NOT NULL DEFAULT 'test' CHECK (environment IN ('test', 'live')), checkout_status TEXT NOT NULL DEFAULT 'checkout_pending' CHECK (checkout_status IN ('checkout_pending', 'checkout_created', 'checkout_failed')), stripe_checkout_url TEXT CHECK (stripe_checkout_url IS NULL OR length(stripe_checkout_url) BETWEEN 1 AND 2048), stripe_payment_intent_id TEXT CHECK (stripe_payment_intent_id IS NULL OR length(stripe_payment_intent_id) BETWEEN 1 AND 255), checkout_failure_code TEXT CHECK (checkout_failure_code IS NULL OR length(checkout_failure_code) BETWEEN 1 AND 80), checkout_created_at TEXT, payment_confirmed_at TEXT, payment_failed_at TEXT, customer_id TEXT REFERENCES commerce_customers(id) ON DELETE RESTRICT, product_subtotal_amount INTEGER NOT NULL DEFAULT 0 CHECK (product_subtotal_amount BETWEEN 0 AND 2147483647), shipping_amount INTEGER NOT NULL DEFAULT 0 CHECK (shipping_amount BETWEEN 0 AND 2147483647), tax_amount INTEGER NOT NULL DEFAULT 0 CHECK (tax_amount BETWEEN 0 AND 2147483647), tax_status TEXT NOT NULL DEFAULT 'not_calculated'
  CHECK (tax_status IN ('not_calculated', 'calculating', 'complete', 'not_collecting', 'failed')), tax_reason TEXT CHECK (tax_reason IS NULL OR length(tax_reason) BETWEEN 1 AND 160));
CREATE TABLE commerce_audit (
  id TEXT PRIMARY KEY,
  actor_account_id TEXT,
  action TEXT NOT NULL,
  target_type TEXT NOT NULL,
  target_id TEXT,
  result TEXT NOT NULL CHECK (result IN ('success', 'rejected', 'error')),
  metadata_json TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "commerce_webhook_events" (
  provider TEXT NOT NULL CHECK (provider = 'stripe'),
  provider_event_id TEXT NOT NULL CHECK (length(provider_event_id) BETWEEN 1 AND 255),
  event_type TEXT NOT NULL CHECK (length(event_type) BETWEEN 1 AND 255),
  event_created_at INTEGER CHECK (event_created_at IS NULL OR event_created_at >= 0),
  received_at TEXT NOT NULL,
  livemode INTEGER NOT NULL CHECK (livemode IN (0, 1)),
  api_version TEXT CHECK (api_version IS NULL OR length(api_version) BETWEEN 1 AND 80),
  related_object_id TEXT CHECK (related_object_id IS NULL OR length(related_object_id) BETWEEN 1 AND 255),
  related_object_type TEXT CHECK (related_object_type IS NULL OR length(related_object_type) BETWEEN 1 AND 120),
  processing_status TEXT NOT NULL CHECK (processing_status IN ('received', 'accepted_noop', 'processed', 'ignored', 'error')),
  processed_at TEXT,
  result_code TEXT CHECK (result_code IS NULL OR length(result_code) BETWEEN 1 AND 80),
  payload_sha256 TEXT CHECK (payload_sha256 IS NULL OR (length(payload_sha256) = 64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*')),
  PRIMARY KEY (provider, provider_event_id)
);
CREATE TABLE community_submissions (
  id TEXT PRIMARY KEY CHECK (length(id) = 36),
  reference_code TEXT NOT NULL UNIQUE CHECK (length(reference_code) BETWEEN 8 AND 24),
  public_slug TEXT UNIQUE CHECK (public_slug IS NULL OR (length(public_slug) BETWEEN 3 AND 120 AND public_slug NOT GLOB '*[^a-z0-9-]*')),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'pending', 'approved', 'rejected')),
  is_published INTEGER NOT NULL DEFAULT 0 CHECK (is_published IN (0, 1)),
  draft_token_hash TEXT CHECK (draft_token_hash IS NULL OR length(draft_token_hash) = 64),
  draft_expires_at TEXT,
  submitter_account_id TEXT CHECK (submitter_account_id IS NULL OR length(submitter_account_id) BETWEEN 1 AND 160),
  submitter_email TEXT,
  display_name TEXT,
  description TEXT,
  product_id TEXT,
  product_slug_snapshot TEXT,
  product_name_snapshot TEXT,
  rating INTEGER CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  city TEXT,
  region TEXT,
  country_code TEXT CHECK (country_code IS NULL OR (length(country_code) = 2 AND country_code = upper(country_code))),
  public_location_label TEXT,
  public_latitude REAL CHECK (public_latitude IS NULL OR public_latitude BETWEEN -85 AND 85),
  public_longitude REAL CHECK (public_longitude IS NULL OR public_longitude BETWEEN -180 AND 180),
  location_confirmed_at TEXT,
  consent_version TEXT,
  consented_at TEXT,
  created_at TEXT NOT NULL,
  submitted_at TEXT,
  updated_at TEXT NOT NULL,
  approved_at TEXT,
  rejected_at TEXT,
  moderator_account_id TEXT,
  moderator_note TEXT,
  rejection_reason TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), comment_mode TEXT NOT NULL DEFAULT 'inherit'
  CHECK (comment_mode IN ('inherit', 'disabled', 'auto', 'moderated')), reaction_mode TEXT NOT NULL DEFAULT 'inherit'
  CHECK (reaction_mode IN ('inherit', 'disabled', 'auto', 'moderated')), legacy_source TEXT, legacy_source_id TEXT, legacy_owner_id TEXT, legacy_product_url TEXT, legacy_uploaded_at TEXT, legacy_updated_at TEXT, legacy_like_count INTEGER NOT NULL DEFAULT 0 CHECK (legacy_like_count >= 0), legacy_dislike_count INTEGER NOT NULL DEFAULT 0 CHECK (legacy_dislike_count >= 0), legacy_comment_count INTEGER NOT NULL DEFAULT 0 CHECK (legacy_comment_count >= 0),
  CHECK (status <> 'draft' OR (draft_token_hash IS NOT NULL AND draft_expires_at IS NOT NULL)),
  CHECK (status <> 'approved' OR (public_slug IS NOT NULL AND approved_at IS NOT NULL)),
  CHECK (is_published = 0 OR status = 'approved'),
  FOREIGN KEY (product_id) REFERENCES commerce_products(id) ON DELETE RESTRICT
);
CREATE TABLE community_reactions (
  submission_id TEXT NOT NULL,
  account_id TEXT NOT NULL CHECK (length(account_id) BETWEEN 1 AND 160),
  value INTEGER NOT NULL CHECK (value IN (-1, 1)),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, moderation_state TEXT NOT NULL DEFAULT 'approved'
  CHECK (moderation_state IN ('approved', 'pending', 'hidden')), moderated_by_account_id TEXT, moderated_at TEXT,
  PRIMARY KEY (submission_id, account_id),
  FOREIGN KEY (submission_id) REFERENCES community_submissions(id) ON DELETE CASCADE
);
CREATE TABLE community_comments (
  id TEXT PRIMARY KEY CHECK (length(id) = 36),
  submission_id TEXT NOT NULL,
  account_id TEXT NOT NULL CHECK (length(account_id) BETWEEN 1 AND 160),
  author_display_name TEXT NOT NULL CHECK (length(author_display_name) BETWEEN 1 AND 80),
  author_avatar_url TEXT,
  body TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 1200),
  status TEXT NOT NULL DEFAULT 'visible' CHECK (status IN ('visible', 'hidden', 'deleted')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  moderated_by_account_id TEXT,
  moderated_at TEXT, moderation_state TEXT NOT NULL DEFAULT 'approved'
  CHECK (moderation_state IN ('approved', 'pending', 'hidden')),
  FOREIGN KEY (submission_id) REFERENCES community_submissions(id) ON DELETE CASCADE
);
CREATE TABLE community_moderation_events (
  id TEXT PRIMARY KEY CHECK (length(id) = 36),
  submission_id TEXT NOT NULL,
  actor_account_id TEXT,
  event_type TEXT NOT NULL CHECK (event_type IN ('submitted', 'updated', 'approved', 'rejected', 'hidden', 'restored', 'comment_hidden', 'comment_restored', 'email_retried')),
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  FOREIGN KEY (submission_id) REFERENCES community_submissions(id) ON DELETE CASCADE
);
CREATE TABLE community_email_templates (
  template_key TEXT PRIMARY KEY CHECK (template_key IN ('goat_submission_received', 'goat_submission_admin_alert', 'goat_submission_approved', 'goat_submission_rejected')),
  subject TEXT NOT NULL CHECK (length(subject) BETWEEN 1 AND 200),
  html_body TEXT NOT NULL CHECK (length(html_body) BETWEEN 1 AND 20000),
  text_body TEXT NOT NULL CHECK (length(text_body) BETWEEN 1 AND 10000),
  variables_json TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disabled', 'ready')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
);
CREATE TABLE community_email_outbox (
  id TEXT PRIMARY KEY CHECK (length(id) = 36),
  template_key TEXT NOT NULL,
  recipient_email TEXT NOT NULL,
  submission_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) BETWEEN 12 AND 180),
  variables_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 20),
  last_error TEXT,
  provider_message_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  sent_at TEXT,
  FOREIGN KEY (template_key) REFERENCES community_email_templates(template_key) ON DELETE RESTRICT,
  FOREIGN KEY (submission_id) REFERENCES community_submissions(id) ON DELETE CASCADE
);
CREATE TABLE community_rate_limits (
  key_hash TEXT NOT NULL CHECK (length(key_hash) = 64),
  category TEXT NOT NULL CHECK (category IN ('draft', 'upload', 'finalise', 'reaction', 'comment')),
  window_started_at TEXT NOT NULL,
  request_count INTEGER NOT NULL DEFAULT 1 CHECK (request_count >= 1),
  blocked_until TEXT,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (key_hash, category)
);
CREATE TABLE commerce_product_variants (
  id TEXT PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 160),
  product_id TEXT NOT NULL,
  local_variant_key TEXT NOT NULL CHECK (length(local_variant_key) BETWEEN 1 AND 180),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'restricted', 'disabled', 'error')),
  visibility TEXT NOT NULL DEFAULT 'private'
    CHECK (visibility IN ('private', 'public')),
  is_sellable INTEGER NOT NULL DEFAULT 0 CHECK (is_sellable IN (0, 1)),
  availability_status TEXT NOT NULL DEFAULT 'active'
    CHECK (availability_status IN ('active', 'temporarily_out_of_stock', 'discontinued')),
  is_ignored INTEGER NOT NULL DEFAULT 0 CHECK (is_ignored IN (0, 1)),
  unit_amount INTEGER NOT NULL CHECK (unit_amount BETWEEN 1 AND 100000000),
  currency_code TEXT NOT NULL DEFAULT 'CAD' CHECK (currency_code = 'CAD'),
  sku TEXT CHECK (sku IS NULL OR length(sku) BETWEEN 1 AND 240),
  size_label TEXT CHECK (size_label IS NULL OR length(size_label) BETWEEN 1 AND 120),
  color_label TEXT CHECK (color_label IS NULL OR length(color_label) BETWEEN 1 AND 120),
  option_values_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(option_values_json) AND json_type(option_values_json) = 'object' AND length(option_values_json) <= 4096),
  target_printful_product_id TEXT
    CHECK (target_printful_product_id IS NULL OR length(target_printful_product_id) BETWEEN 1 AND 240),
  target_printful_external_id TEXT
    CHECK (target_printful_external_id IS NULL OR length(target_printful_external_id) BETWEEN 1 AND 240),
  target_printful_sync_variant_id TEXT
    CHECK (target_printful_sync_variant_id IS NULL OR length(target_printful_sync_variant_id) BETWEEN 1 AND 240),
  target_catalogue_product_id TEXT
    CHECK (target_catalogue_product_id IS NULL OR length(target_catalogue_product_id) BETWEEN 1 AND 240),
  target_catalogue_variant_id TEXT
    CHECK (target_catalogue_variant_id IS NULL OR length(target_catalogue_variant_id) BETWEEN 1 AND 240),
  legacy_source_product_id TEXT
    CHECK (legacy_source_product_id IS NULL OR length(legacy_source_product_id) BETWEEN 1 AND 240),
  legacy_source_variant_id TEXT
    CHECK (legacy_source_variant_id IS NULL OR length(legacy_source_variant_id) BETWEEN 1 AND 240),
  legacy_wix_external_product_id TEXT
    CHECK (legacy_wix_external_product_id IS NULL OR length(legacy_wix_external_product_id) BETWEEN 1 AND 240),
  legacy_wix_external_variant_id TEXT
    CHECK (legacy_wix_external_variant_id IS NULL OR length(legacy_wix_external_variant_id) BETWEEN 1 AND 240),
  fulfillment_provider TEXT NOT NULL DEFAULT 'printful'
    CHECK (fulfillment_provider IN ('printful', 'printify', 'manual', 'none')),
  fulfillment_mapping_status TEXT NOT NULL DEFAULT 'unmapped'
    CHECK (fulfillment_mapping_status IN ('unmapped', 'planned', 'provider_processing', 'mapped', 'conflict', 'manual_review')),
  migration_status TEXT NOT NULL DEFAULT 'selected'
    CHECK (migration_status IN ('selected', 'deferred', 'target_created', 'provider_processing', 'target_verified', 'blocked', 'excluded', 'target_native')),
  migration_provenance_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(migration_provenance_json) AND json_type(migration_provenance_json) = 'object' AND length(migration_provenance_json) <= 16384),
  file_mapping_json TEXT NOT NULL DEFAULT '[]'
    CHECK (json_valid(file_mapping_json) AND json_type(file_mapping_json) = 'array' AND length(file_mapping_json) <= 32768),
  safe_metadata_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(safe_metadata_json) AND json_type(safe_metadata_json) = 'object' AND length(safe_metadata_json) <= 16384),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (product_id) REFERENCES commerce_products(id) ON DELETE RESTRICT,
  UNIQUE (product_id, local_variant_key),
  UNIQUE (target_printful_external_id),
  UNIQUE (target_printful_sync_variant_id),
  UNIQUE (legacy_source_variant_id),
  UNIQUE (legacy_wix_external_product_id, legacy_wix_external_variant_id)
);
CREATE TABLE commerce_printful_file_mappings (
  source_store_id TEXT NOT NULL CHECK (length(source_store_id) BETWEEN 1 AND 40),
  source_file_id TEXT NOT NULL CHECK (length(source_file_id) BETWEEN 1 AND 240),
  source_url TEXT NOT NULL CHECK (length(source_url) BETWEEN 9 AND 4096 AND source_url LIKE 'https://%'),
  filename TEXT NOT NULL CHECK (length(filename) BETWEEN 1 AND 500),
  file_status TEXT NOT NULL CHECK (file_status IN ('ok', 'accepted')),
  safe_metadata_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(safe_metadata_json) AND json_type(safe_metadata_json) = 'object' AND length(safe_metadata_json) <= 8192),
  resolved_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (source_store_id, source_file_id)
);
CREATE TABLE commerce_catalogue_migrations (
  id TEXT PRIMARY KEY CHECK (id = 'permanent-printful-2026-08'),
  status TEXT NOT NULL DEFAULT 'ready'
    CHECK (status IN ('ready', 'running', 'waiting', 'completed', 'blocked')),
  phase TEXT NOT NULL DEFAULT 'preflight'
    CHECK (phase IN ('preflight', 'source_product', 'source_files', 'target_lookup', 'target_create', 'target_verify', 'd1_mapping', 'completed', 'blocked')),
  current_product_id TEXT,
  provider_request_count INTEGER NOT NULL DEFAULT 0 CHECK (provider_request_count >= 0),
  products_created INTEGER NOT NULL DEFAULT 0 CHECK (products_created >= 0),
  products_adopted INTEGER NOT NULL DEFAULT 0 CHECK (products_adopted >= 0),
  products_verified INTEGER NOT NULL DEFAULT 0 CHECK (products_verified >= 0),
  variants_mapped INTEGER NOT NULL DEFAULT 0 CHECK (variants_mapped >= 0),
  provider_failures INTEGER NOT NULL DEFAULT 0 CHECK (provider_failures >= 0),
  last_provider_request_at INTEGER CHECK (last_provider_request_at IS NULL OR last_provider_request_at >= 0),
  next_provider_request_at INTEGER CHECK (next_provider_request_at IS NULL OR next_provider_request_at >= 0),
  throttle_until INTEGER CHECK (throttle_until IS NULL OR throttle_until >= 0),
  last_http_status INTEGER CHECK (last_http_status IS NULL OR last_http_status BETWEEN 100 AND 599),
  safe_state_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(safe_state_json) AND json_type(safe_state_json) = 'object' AND length(safe_state_json) <= 65536),
  step_lease_token TEXT CHECK (step_lease_token IS NULL OR length(step_lease_token) BETWEEN 16 AND 80),
  step_lease_expires_at INTEGER CHECK (step_lease_expires_at IS NULL OR step_lease_expires_at >= 0),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  started_at TEXT,
  updated_at TEXT NOT NULL,
  completed_at TEXT,
  FOREIGN KEY (current_product_id) REFERENCES commerce_products(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS "commerce_order_items" (
  id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL,
  line_number INTEGER NOT NULL CHECK (line_number BETWEEN 1 AND 20),
  product_id TEXT NOT NULL CHECK (length(product_id) BETWEEN 1 AND 160),
  variant_id TEXT CHECK (variant_id IS NULL OR length(variant_id) BETWEEN 1 AND 160),
  product_name TEXT NOT NULL CHECK (length(product_name) BETWEEN 1 AND 240),
  variant_name TEXT CHECK (variant_name IS NULL OR length(variant_name) BETWEEN 1 AND 300),
  sku TEXT CHECK (sku IS NULL OR length(sku) BETWEEN 1 AND 240),
  option_values_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(option_values_json) AND json_type(option_values_json) = 'object' AND length(option_values_json) <= 4096),
  currency_code TEXT NOT NULL CHECK (currency_code = 'CAD'),
  unit_amount INTEGER NOT NULL CHECK (unit_amount BETWEEN 1 AND 100000000),
  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 20),
  line_total_amount INTEGER NOT NULL CHECK (line_total_amount = unit_amount * quantity AND line_total_amount > 0),
  requires_shipping INTEGER NOT NULL DEFAULT 0 CHECK (requires_shipping IN (0, 1)),
  fulfillment_provider TEXT CHECK (fulfillment_provider IN ('printful', 'printify', 'manual', 'none')),
  fulfillment_variant_id TEXT CHECK (fulfillment_variant_id IS NULL OR length(fulfillment_variant_id) BETWEEN 1 AND 240),
  created_at TEXT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (product_id) REFERENCES commerce_products(id) ON DELETE RESTRICT,
  FOREIGN KEY (variant_id) REFERENCES commerce_product_variants(id) ON DELETE RESTRICT,
  UNIQUE (order_id, line_number),
  UNIQUE (order_id, product_id, variant_id)
);
CREATE TABLE site_banner_settings (
  id TEXT PRIMARY KEY CHECK (id = 'global-banner'),
  config_json TEXT NOT NULL CHECK (json_valid(config_json) AND json_type(config_json) = 'object' AND length(config_json) <= 16384),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
);
CREATE TABLE commerce_collections (
  id TEXT PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 160),
  slug TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 180 AND slug NOT GLOB '*[^a-z0-9-]*'),
  title TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK (length(title) BETWEEN 1 AND 160),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
  visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'hidden')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
  display_order INTEGER NOT NULL DEFAULT 1000 CHECK (display_order BETWEEN 0 AND 999999),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
);
CREATE TABLE commerce_product_collections (
  product_id TEXT NOT NULL,
  collection_id TEXT NOT NULL,
  assigned_at TEXT NOT NULL,
  assigned_by_account_id TEXT,
  PRIMARY KEY (product_id, collection_id),
  FOREIGN KEY (product_id) REFERENCES commerce_products(id) ON DELETE RESTRICT,
  FOREIGN KEY (collection_id) REFERENCES commerce_collections(id) ON DELETE RESTRICT
);
CREATE TABLE IF NOT EXISTS "community_media" (
  id TEXT PRIMARY KEY CHECK (length(id) = 36),
  submission_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('main', 'profile', 'gallery')),
  sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order BETWEEN 0 AND 5),
  object_key TEXT NOT NULL UNIQUE CHECK (length(object_key) BETWEEN 40 AND 240),
  content_type TEXT NOT NULL CHECK (
    content_type IN ('image/jpeg', 'image/png', 'image/webp')
    OR (role = 'profile' AND content_type = 'image/gif')
  ),
  byte_size INTEGER NOT NULL CHECK (byte_size BETWEEN 1 AND 10485760),
  width INTEGER NOT NULL CHECK (width BETWEEN 1 AND 12000),
  height INTEGER NOT NULL CHECK (height BETWEEN 1 AND 12000),
  sha256 TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
  processing_state TEXT NOT NULL DEFAULT 'ready' CHECK (processing_state IN ('pending', 'ready', 'failed')),
  processing_error TEXT,
  created_at TEXT NOT NULL,
  FOREIGN KEY (submission_id) REFERENCES community_submissions(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "commerce_tax_registrations" (
  id TEXT PRIMARY KEY,
  business_profile_id TEXT NOT NULL DEFAULT 'primary',
  registration_type TEXT NOT NULL CHECK (registration_type IN ('business_number', 'gst_hst', 'qst', 'pst', 'rst', 'other', 'provincial')),
  jurisdiction TEXT NOT NULL CHECK (length(jurisdiction) BETWEEN 2 AND 80),
  country_code TEXT NOT NULL DEFAULT 'CA' CHECK (length(country_code) = 2),
  province_code TEXT CHECK (province_code IS NULL OR length(province_code) BETWEEN 2 AND 3),
  identifier_ciphertext TEXT NOT NULL,
  masked_identifier TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'unverified' CHECK (status IN ('unverified', 'pending', 'verified', 'active', 'inactive', 'expired', 'not_registered', 'unavailable')),
  effective_date TEXT,
  expires_at TEXT,
  notes TEXT,
  document_disclosure_enabled INTEGER NOT NULL DEFAULT 0 CHECK (document_disclosure_enabled IN (0, 1)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT,
  FOREIGN KEY (business_profile_id) REFERENCES commerce_business_profiles(id) ON DELETE CASCADE,
  UNIQUE (business_profile_id, registration_type, jurisdiction)
);
CREATE TABLE IF NOT EXISTS "commerce_templates" (
  id TEXT PRIMARY KEY,
  template_key TEXT NOT NULL UNIQUE CHECK (template_key IN ('order_confirmation', 'shipment_notification', 'cancellation', 'refund', 'payment_failure', 'invoice_notification', 'receipt_notification', 'payment_receipt', 'invoice_document')),
  template_kind TEXT NOT NULL DEFAULT 'email' CHECK (template_kind IN ('email', 'document')),
  display_name TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
  subject TEXT NOT NULL,
  preheader TEXT NOT NULL DEFAULT '',
  heading TEXT NOT NULL,
  introduction TEXT NOT NULL DEFAULT '',
  body_blocks_json TEXT NOT NULL DEFAULT '[]',
  cta_label TEXT NOT NULL DEFAULT '',
  cta_url TEXT NOT NULL DEFAULT '',
  support_text TEXT NOT NULL DEFAULT '',
  footer TEXT NOT NULL DEFAULT '',
  accent_color TEXT NOT NULL DEFAULT '#f3c928',
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'disabled', 'ready')),
  enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
);
CREATE TABLE commerce_email_deliveries (
  id TEXT PRIMARY KEY,
  delivery_key TEXT NOT NULL UNIQUE CHECK (length(delivery_key) = 64 AND delivery_key NOT GLOB '*[^0-9a-f]*'),
  template_key TEXT NOT NULL,
  template_revision INTEGER NOT NULL CHECK (template_revision >= 1),
  order_id TEXT,
  event_key TEXT NOT NULL CHECK (length(event_key) BETWEEN 1 AND 200),
  recipient_email TEXT NOT NULL CHECK (length(recipient_email) BETWEEN 3 AND 254),
  purpose TEXT NOT NULL CHECK (purpose IN ('transactional', 'test_preview')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sending', 'sent', 'failed')),
  provider_message_id TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  safe_metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  sent_at TEXT, recipient_email_ciphertext TEXT
  CHECK (recipient_email_ciphertext IS NULL OR length(recipient_email_ciphertext) BETWEEN 80 AND 8192),
  FOREIGN KEY (template_key) REFERENCES commerce_templates(template_key) ON DELETE RESTRICT,
  FOREIGN KEY (order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT
);
CREATE TABLE commerce_order_documents (
  id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL,
  document_type TEXT NOT NULL CHECK (document_type IN ('receipt', 'invoice')),
  display_reference TEXT NOT NULL CHECK (length(display_reference) BETWEEN 1 AND 180),
  environment TEXT NOT NULL CHECK (environment IN ('test', 'live')),
  status TEXT NOT NULL DEFAULT 'preview' CHECK (status IN ('preview', 'issued', 'revoked')),
  template_key TEXT NOT NULL,
  template_revision INTEGER NOT NULL CHECK (template_revision >= 1),
  snapshot_json TEXT NOT NULL,
  access_token_hash TEXT UNIQUE CHECK (access_token_hash IS NULL OR (length(access_token_hash) = 64 AND access_token_hash NOT GLOB '*[^0-9a-f]*')),
  issued_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (template_key) REFERENCES commerce_templates(template_key) ON DELETE RESTRICT,
  UNIQUE (order_id, document_type)
);
CREATE TABLE admin_inbox_messages (
  id TEXT PRIMARY KEY,
  category TEXT NOT NULL,
  source_type TEXT NOT NULL,
  source_id TEXT NOT NULL,
  title TEXT NOT NULL,
  preview TEXT NOT NULL,
  body_text TEXT NOT NULL,
  action_url TEXT,
  action_label TEXT,
  created_at TEXT NOT NULL,
  resolved_at TEXT,
  UNIQUE(source_type, source_id)
);
CREATE TABLE admin_inbox_reads (
  message_id TEXT NOT NULL REFERENCES admin_inbox_messages(id) ON DELETE CASCADE,
  account_id TEXT NOT NULL,
  read_at TEXT NOT NULL,
  PRIMARY KEY(message_id, account_id)
);
CREATE TABLE wheel_settings (
  setting_key TEXT PRIMARY KEY,
  value_json TEXT NOT NULL CHECK (json_valid(value_json)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  updated_at TEXT NOT NULL,
  updated_by_account_id TEXT
);
CREATE TABLE wheels (
  id TEXT PRIMARY KEY,
  reference_code TEXT NOT NULL UNIQUE,
  public_slug TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK (length(public_slug) BETWEEN 3 AND 80),
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 100),
  description TEXT CHECK (description IS NULL OR length(description) <= 280),
  lifecycle TEXT NOT NULL DEFAULT 'draft' CHECK (lifecycle IN ('draft', 'active', 'archived')),
  visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'hidden')),
  owner_account_id TEXT NOT NULL CHECK (length(owner_account_id) BETWEEN 1 AND 160),
  display_order INTEGER NOT NULL DEFAULT 0,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  spin_sequence INTEGER NOT NULL DEFAULT 0 CHECK (spin_sequence >= 0),
  official_spin_enabled INTEGER NOT NULL DEFAULT 1 CHECK (official_spin_enabled IN (0, 1)),
  public_demo_spin_enabled INTEGER NOT NULL DEFAULT 1 CHECK (public_demo_spin_enabled IN (0, 1)),
  editing_locked INTEGER NOT NULL DEFAULT 0 CHECK (editing_locked IN (0, 1)),
  official_spinning_locked INTEGER NOT NULL DEFAULT 0 CHECK (official_spinning_locked IN (0, 1)),
  config_json TEXT NOT NULL CHECK (json_valid(config_json) AND length(config_json) <= 8192),
  participant_count INTEGER NOT NULL DEFAULT 0 CHECK (participant_count BETWEEN 0 AND 1000),
  latest_official_spin_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  archived_at TEXT
);
CREATE TABLE wheel_entries (
  id TEXT PRIMARY KEY,
  wheel_id TEXT NOT NULL REFERENCES wheels(id) ON DELETE CASCADE,
  display_label TEXT NOT NULL CHECK (length(display_label) BETWEEN 1 AND 120),
  display_order INTEGER NOT NULL CHECK (display_order >= 0),
  weight INTEGER NOT NULL DEFAULT 1 CHECK (weight BETWEEN 1 AND 100000),
  segment_colour TEXT CHECK (segment_colour IS NULL OR (length(segment_colour) = 7 AND substr(segment_colour, 1, 1) = '#' AND substr(segment_colour, 2) NOT GLOB '*[^0-9A-Fa-f]*')),
  state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('active', 'hidden')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (wheel_id, display_order)
);
CREATE TABLE wheel_creator_grants (
  account_id TEXT PRIMARY KEY CHECK (length(account_id) BETWEEN 1 AND 160),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  may_create_wheels INTEGER NOT NULL DEFAULT 1 CHECK (may_create_wheels IN (0, 1)),
  maximum_owned_wheels INTEGER CHECK (maximum_owned_wheels IS NULL OR maximum_owned_wheels BETWEEN 1 AND 100),
  granted_by_account_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  revoked_at TEXT
);
CREATE TABLE wheel_access (
  wheel_id TEXT NOT NULL REFERENCES wheels(id) ON DELETE CASCADE,
  account_id TEXT NOT NULL CHECK (length(account_id) BETWEEN 1 AND 160),
  role TEXT NOT NULL CHECK (role IN ('owner', 'editor', 'spinner')),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  granted_by_account_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  revoked_at TEXT,
  PRIMARY KEY (wheel_id, account_id)
);
CREATE TABLE wheel_official_spins (
  id TEXT PRIMARY KEY,
  wheel_id TEXT NOT NULL REFERENCES wheels(id) ON DELETE RESTRICT,
  wheel_revision INTEGER NOT NULL CHECK (wheel_revision >= 1),
  participant_snapshot_hash TEXT NOT NULL CHECK (length(participant_snapshot_hash) = 64),
  winning_entry_id TEXT NOT NULL,
  winning_label_snapshot TEXT NOT NULL CHECK (length(winning_label_snapshot) BETWEEN 1 AND 120),
  winning_weight_snapshot INTEGER NOT NULL CHECK (winning_weight_snapshot BETWEEN 1 AND 100000),
  performed_by_account_id TEXT NOT NULL,
  result_type TEXT NOT NULL DEFAULT 'official' CHECK (result_type = 'official'),
  idempotency_key TEXT NOT NULL CHECK (length(idempotency_key) BETWEEN 16 AND 120),
  created_at TEXT NOT NULL,
  voided_at TEXT,
  void_reason TEXT CHECK (void_reason IS NULL OR length(void_reason) BETWEEN 3 AND 500),
  voided_by_account_id TEXT,
  UNIQUE (wheel_id, idempotency_key)
);
CREATE TABLE wheel_audit_events (
  id TEXT PRIMARY KEY,
  wheel_id TEXT REFERENCES wheels(id) ON DELETE SET NULL,
  actor_account_id TEXT,
  target_account_id TEXT,
  event_type TEXT NOT NULL CHECK (length(event_type) BETWEEN 3 AND 80),
  metadata_json TEXT CHECK (metadata_json IS NULL OR (json_valid(metadata_json) AND length(metadata_json) <= 8192)),
  created_at TEXT NOT NULL
);
CREATE TABLE wheel_rate_limits (
  key_hash TEXT NOT NULL,
  category TEXT NOT NULL,
  window_started_at TEXT NOT NULL,
  request_count INTEGER NOT NULL DEFAULT 0 CHECK (request_count >= 0),
  blocked_until TEXT,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (key_hash, category)
);
CREATE TABLE wheel_media_assets (
  id TEXT PRIMARY KEY CHECK (length(id) BETWEEN 16 AND 80),
  wheel_id TEXT NOT NULL REFERENCES wheels(id) ON DELETE CASCADE,
  purpose TEXT NOT NULL CHECK (purpose IN ('background', 'centre')),
  object_key TEXT NOT NULL UNIQUE CHECK (length(object_key) BETWEEN 20 AND 500),
  sha256 TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
  content_type TEXT NOT NULL CHECK (content_type IN ('image/png', 'image/jpeg', 'image/webp', 'image/bmp', 'image/svg+xml')),
  byte_size INTEGER NOT NULL CHECK (byte_size BETWEEN 1 AND 8388608),
  width INTEGER CHECK (width IS NULL OR width BETWEEN 1 AND 12000),
  height INTEGER CHECK (height IS NULL OR height BETWEEN 1 AND 12000),
  lifecycle TEXT NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active', 'deleted')),
  uploaded_by_account_id TEXT NOT NULL CHECK (length(uploaded_by_account_id) BETWEEN 1 AND 160),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
);
CREATE TABLE commerce_shipping_quotes (
  id TEXT PRIMARY KEY CHECK (id GLOB 'shq_*' AND length(id) BETWEEN 40 AND 80),
  environment TEXT NOT NULL CHECK (environment IN ('test', 'live')),
  cart_fingerprint TEXT NOT NULL CHECK (length(cart_fingerprint) = 64 AND cart_fingerprint NOT GLOB '*[^0-9a-f]*'),
  recipient_fingerprint TEXT NOT NULL CHECK (length(recipient_fingerprint) = 64 AND recipient_fingerprint NOT GLOB '*[^0-9a-f]*'),
  currency_code TEXT NOT NULL CHECK (currency_code = 'CAD'),
  shipping_strategy TEXT NOT NULL CHECK (shipping_strategy IN ('none', 'printful_dynamic')),
  provider TEXT CHECK (provider IS NULL OR provider = 'printful'),
  rate_options_json TEXT NOT NULL
    CHECK (json_valid(rate_options_json) AND json_type(rate_options_json) = 'array' AND length(rate_options_json) BETWEEN 2 AND 16384),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE TABLE commerce_order_delivery_snapshots (
  order_id TEXT PRIMARY KEY,
  recipient_ciphertext TEXT NOT NULL CHECK (length(recipient_ciphertext) BETWEEN 80 AND 8192),
  destination_country_code TEXT NOT NULL CHECK (length(destination_country_code) = 2),
  destination_region_code TEXT CHECK (destination_region_code IS NULL OR length(destination_region_code) BETWEEN 1 AND 80),
  shipping_strategy TEXT NOT NULL CHECK (shipping_strategy IN ('none', 'printful_dynamic')),
  provider TEXT CHECK (provider IS NULL OR provider = 'printful'),
  provider_shipping_method_id TEXT CHECK (provider_shipping_method_id IS NULL OR length(provider_shipping_method_id) BETWEEN 1 AND 120),
  display_shipping_method TEXT NOT NULL CHECK (length(display_shipping_method) BETWEEN 1 AND 100),
  shipping_amount INTEGER NOT NULL CHECK (shipping_amount BETWEEN 0 AND 2147483647),
  currency_code TEXT NOT NULL CHECK (currency_code = 'CAD'),
  source_quote_id TEXT NOT NULL UNIQUE,
  quoted_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (source_quote_id) REFERENCES commerce_shipping_quotes(id) ON DELETE RESTRICT
);
CREATE TABLE commerce_customers (
  id TEXT PRIMARY KEY CHECK (id GLOB 'cst_*' AND length(id) BETWEEN 40 AND 80),
  customer_kind TEXT NOT NULL CHECK (customer_kind IN ('guest', 'account')),
  linked_account_id TEXT,
  contact_name_ciphertext TEXT NOT NULL CHECK (length(contact_name_ciphertext) BETWEEN 80 AND 8192),
  contact_email_ciphertext TEXT NOT NULL CHECK (length(contact_email_ciphertext) BETWEEN 80 AND 8192),
  contact_email_fingerprint TEXT NOT NULL
    CHECK (length(contact_email_fingerprint) BETWEEN 40 AND 64),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, contact_phone_ciphertext TEXT
  CHECK (contact_phone_ciphertext IS NULL OR length(contact_phone_ciphertext) BETWEEN 80 AND 8192),
  CHECK (
    (customer_kind = 'guest' AND linked_account_id IS NULL)
    OR
    (customer_kind = 'account' AND linked_account_id IS NOT NULL AND length(linked_account_id) BETWEEN 1 AND 160)
  )
);
CREATE TABLE commerce_fulfillment_orders (
  id TEXT PRIMARY KEY CHECK (id GLOB 'flo_*' AND length(id) BETWEEN 40 AND 80),
  order_id TEXT NOT NULL,
  provider TEXT NOT NULL CHECK (provider = 'printful'),
  provider_store_id TEXT NOT NULL CHECK (length(provider_store_id) BETWEEN 1 AND 40),
  provider_order_id TEXT NOT NULL CHECK (length(provider_order_id) BETWEEN 1 AND 80),
  external_id TEXT NOT NULL CHECK (length(external_id) BETWEEN 1 AND 160),
  environment TEXT NOT NULL CHECK (environment IN ('test', 'live')),
  provider_state TEXT NOT NULL CHECK (provider_state IN (
    'draft', 'submitted', 'processing', 'on_hold', 'partial', 'complete',
    'failed', 'canceled', 'archived', 'unknown'
  )),
  fulfillment_state TEXT NOT NULL CHECK (fulfillment_state IN (
    'unfulfilled', 'processing', 'partial', 'shipped', 'delivered',
    'returned', 'action_required', 'canceled', 'unknown'
  )),
  confirmation_state TEXT NOT NULL CHECK (confirmation_state IN ('unconfirmed', 'submitted', 'unknown')),
  provider_status TEXT NOT NULL CHECK (length(provider_status) BETWEEN 1 AND 40),
  failure_category TEXT CHECK (failure_category IS NULL OR length(failure_category) BETWEEN 1 AND 80),
  provider_created_at TEXT,
  provider_updated_at TEXT,
  last_provider_evidence_at TEXT NOT NULL,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT,
  UNIQUE (order_id, provider),
  UNIQUE (provider, provider_store_id, provider_order_id),
  UNIQUE (provider, provider_store_id, external_id)
);
CREATE TABLE commerce_fulfillment_order_items (
  id TEXT PRIMARY KEY CHECK (id GLOB 'fli_*' AND length(id) BETWEEN 40 AND 80),
  fulfillment_order_id TEXT NOT NULL,
  order_item_id TEXT NOT NULL,
  provider_order_item_id TEXT CHECK (provider_order_item_id IS NULL OR length(provider_order_item_id) BETWEEN 1 AND 80),
  provider_variant_id TEXT CHECK (provider_variant_id IS NULL OR length(provider_variant_id) BETWEEN 1 AND 160),
  ordered_quantity INTEGER NOT NULL CHECK (ordered_quantity BETWEEN 1 AND 1000),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (fulfillment_order_id) REFERENCES commerce_fulfillment_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (order_item_id) REFERENCES commerce_order_items(id) ON DELETE RESTRICT,
  UNIQUE (fulfillment_order_id, order_item_id)
);
CREATE TABLE commerce_fulfillment_shipments (
  id TEXT PRIMARY KEY CHECK (id GLOB 'fls_*' AND length(id) BETWEEN 40 AND 80),
  fulfillment_order_id TEXT NOT NULL,
  provider_shipment_id TEXT NOT NULL CHECK (length(provider_shipment_id) BETWEEN 1 AND 80),
  shipment_state TEXT NOT NULL CHECK (shipment_state IN ('shipped', 'delivered', 'returned', 'canceled', 'unknown')),
  provider_status TEXT CHECK (provider_status IS NULL OR length(provider_status) BETWEEN 1 AND 40),
  carrier TEXT CHECK (carrier IS NULL OR length(carrier) BETWEEN 1 AND 80),
  service TEXT CHECK (service IS NULL OR length(service) BETWEEN 1 AND 120),
  tracking_available INTEGER NOT NULL DEFAULT 0 CHECK (tracking_available IN (0, 1)),
  tracking_number_ciphertext TEXT CHECK (tracking_number_ciphertext IS NULL OR length(tracking_number_ciphertext) BETWEEN 80 AND 8192),
  tracking_url_ciphertext TEXT CHECK (tracking_url_ciphertext IS NULL OR length(tracking_url_ciphertext) BETWEEN 80 AND 8192),
  reshipment INTEGER NOT NULL DEFAULT 0 CHECK (reshipment IN (0, 1)),
  reshipment_of_shipment_id TEXT,
  returned_reason_category TEXT CHECK (returned_reason_category IS NULL OR length(returned_reason_category) BETWEEN 1 AND 80),
  provider_created_at TEXT,
  shipped_at TEXT,
  delivered_at TEXT,
  returned_at TEXT,
  last_provider_evidence_at TEXT NOT NULL,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (fulfillment_order_id) REFERENCES commerce_fulfillment_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (reshipment_of_shipment_id) REFERENCES commerce_fulfillment_shipments(id) ON DELETE RESTRICT,
  UNIQUE (fulfillment_order_id, provider_shipment_id),
  CHECK (reshipment_of_shipment_id IS NULL OR reshipment = 1)
);
CREATE TABLE commerce_fulfillment_shipment_items (
  shipment_id TEXT NOT NULL,
  fulfillment_item_id TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 1000),
  created_at TEXT NOT NULL,
  PRIMARY KEY (shipment_id, fulfillment_item_id),
  FOREIGN KEY (shipment_id) REFERENCES commerce_fulfillment_shipments(id) ON DELETE RESTRICT,
  FOREIGN KEY (fulfillment_item_id) REFERENCES commerce_fulfillment_order_items(id) ON DELETE RESTRICT
);
CREATE TABLE commerce_saved_addresses (
  id TEXT PRIMARY KEY CHECK (id GLOB 'adr_*' AND length(id) BETWEEN 40 AND 80),
  customer_id TEXT NOT NULL,
  label TEXT NOT NULL CHECK (length(label) BETWEEN 1 AND 40),
  address_ciphertext TEXT NOT NULL CHECK (length(address_ciphertext) BETWEEN 80 AND 8192),
  country_code TEXT NOT NULL CHECK (length(country_code) = 2),
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),
  lifecycle TEXT NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active', 'deleted')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  FOREIGN KEY (customer_id) REFERENCES commerce_customers(id) ON DELETE RESTRICT,
  CHECK (
    (lifecycle = 'active' AND deleted_at IS NULL)
    OR
    (lifecycle = 'deleted' AND deleted_at IS NOT NULL AND is_default = 0)
  )
);
CREATE TABLE commerce_launch_state (
  id TEXT PRIMARY KEY CHECK (id = 'production'),
  state TEXT NOT NULL CHECK (state IN ('preflight', 'active', 'paused')),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  last_plan_digest TEXT CHECK (last_plan_digest IS NULL OR (length(last_plan_digest) = 64 AND last_plan_digest NOT GLOB '*[^0-9a-f]*')),
  last_plan_json TEXT NOT NULL DEFAULT '{}'
    CHECK (json_valid(last_plan_json) AND json_type(last_plan_json) = 'object' AND length(last_plan_json) <= 32768),
  activated_at TEXT,
  paused_at TEXT,
  pause_reason TEXT CHECK (pause_reason IS NULL OR length(pause_reason) BETWEEN 1 AND 300),
  updated_by_actor TEXT CHECK (updated_by_actor IS NULL OR length(updated_by_actor) BETWEEN 1 AND 160),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE commerce_shipping_markets (
  country_code TEXT PRIMARY KEY CHECK (length(country_code) = 2 AND country_code = upper(country_code)),
  display_name TEXT NOT NULL CHECK (length(display_name) BETWEEN 1 AND 80),
  status TEXT NOT NULL CHECK (status IN ('active', 'disabled')),
  strategy TEXT NOT NULL CHECK (strategy = 'printful_dynamic'),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_actor TEXT CHECK (updated_by_actor IS NULL OR length(updated_by_actor) BETWEEN 1 AND 160)
);
CREATE TABLE IF NOT EXISTS "commerce_provider_webhook_events" (
  id TEXT PRIMARY KEY CHECK (id GLOB 'pwe_*' AND length(id) = 68),
  provider TEXT NOT NULL CHECK (provider = 'printful'),
  event_type TEXT NOT NULL CHECK (event_type IN (
    'order_created', 'order_updated', 'order_failed', 'order_canceled',
    'order_put_hold', 'order_put_hold_approval', 'order_remove_hold', 'order_refunded',
    'shipment_sent', 'shipment_delivered', 'shipment_returned', 'shipment_canceled'
  )),
  occurred_at TEXT NOT NULL,
  provider_store_id TEXT NOT NULL CHECK (length(provider_store_id) BETWEEN 1 AND 40),
  provider_order_id TEXT CHECK (provider_order_id IS NULL OR length(provider_order_id) BETWEEN 1 AND 80),
  provider_shipment_id TEXT CHECK (provider_shipment_id IS NULL OR length(provider_shipment_id) BETWEEN 1 AND 80),
  payload_sha256 TEXT NOT NULL CHECK (length(payload_sha256) = 64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*'),
  processing_status TEXT NOT NULL CHECK (processing_status IN ('received', 'processed', 'ignored', 'unresolved', 'error')),
  result_code TEXT CHECK (result_code IS NULL OR length(result_code) BETWEEN 1 AND 80),
  retry_count INTEGER NOT NULL DEFAULT 0 CHECK (retry_count BETWEEN 0 AND 1000000),
  received_at TEXT NOT NULL,
  processed_at TEXT,
  UNIQUE (provider, payload_sha256)
);
CREATE TABLE commerce_payment_provider_state (
  id TEXT PRIMARY KEY CHECK (id = 'primary'),
  preferred_provider TEXT NOT NULL CHECK (preferred_provider IN ('paypal','stripe')),
  stripe_configured INTEGER NOT NULL CHECK (stripe_configured IN (0,1)),
  stripe_enabled INTEGER NOT NULL CHECK (stripe_enabled IN (0,1)),
  paypal_sandbox_configured INTEGER NOT NULL CHECK (paypal_sandbox_configured IN (0,1)),
  paypal_live_configured INTEGER NOT NULL CHECK (paypal_live_configured IN (0,1)),
  paypal_store_checkout_enabled INTEGER NOT NULL CHECK (paypal_store_checkout_enabled IN (0,1)),
  paypal_live_capture_enabled INTEGER NOT NULL CHECK (paypal_live_capture_enabled IN (0,1)),
  paypal_donations_enabled INTEGER NOT NULL CHECK (paypal_donations_enabled IN (0,1)),
  emergency_paused INTEGER NOT NULL CHECK (emergency_paused IN (0,1)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  transition_reason TEXT NOT NULL CHECK (length(transition_reason) BETWEEN 1 AND 300),
  updated_by_actor TEXT NOT NULL CHECK (length(updated_by_actor) BETWEEN 1 AND 160),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK (stripe_enabled = 0 OR preferred_provider = 'stripe'),
  CHECK (paypal_store_checkout_enabled = 0 OR preferred_provider = 'paypal'),
  CHECK (paypal_live_capture_enabled = 0 OR paypal_live_configured = 1),
  CHECK (paypal_donations_enabled = 0 OR preferred_provider = 'paypal')
);
CREATE TABLE commerce_donations (
  id TEXT PRIMARY KEY CHECK (id GLOB 'don_*' AND length(id) BETWEEN 40 AND 80),
  request_id TEXT NOT NULL UNIQUE CHECK (length(request_id) = 36),
  request_digest TEXT NOT NULL CHECK (length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'),
  customer_id TEXT,
  environment TEXT NOT NULL CHECK (environment IN ('sandbox','live')),
  currency_code TEXT NOT NULL CHECK (currency_code = 'CAD'),
  amount_minor INTEGER NOT NULL CHECK (amount_minor BETWEEN 100 AND 1000000),
  status TEXT NOT NULL CHECK (status IN ('created','approved','pending','completed','failed','refunded','reversed','canceled')),
  donor_display_preference TEXT CHECK (donor_display_preference IS NULL OR donor_display_preference IN ('private')),
  donor_contact_ciphertext TEXT CHECK (donor_contact_ciphertext IS NULL OR length(donor_contact_ciphertext) BETWEEN 80 AND 8192),
  approved_at TEXT,
  completed_at TEXT,
  failed_at TEXT,
  refunded_at TEXT,
  reversed_at TEXT,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES commerce_customers(id) ON DELETE RESTRICT
);
CREATE TABLE commerce_payment_attempts (
  id TEXT PRIMARY KEY CHECK (id GLOB 'pat_*' AND length(id) BETWEEN 40 AND 80),
  commerce_order_id TEXT,
  donation_id TEXT,
  provider TEXT NOT NULL CHECK (provider IN ('paypal','stripe')),
  environment TEXT NOT NULL CHECK (environment IN ('sandbox','test','live')),
  provider_order_id TEXT CHECK (provider_order_id IS NULL OR length(provider_order_id) BETWEEN 1 AND 80),
  provider_capture_id TEXT CHECK (provider_capture_id IS NULL OR length(provider_capture_id) BETWEEN 1 AND 80),
  idempotency_key TEXT NOT NULL CHECK (length(idempotency_key) BETWEEN 16 AND 180),
  currency_code TEXT NOT NULL CHECK (currency_code = 'CAD'),
  amount_minor INTEGER NOT NULL CHECK (amount_minor BETWEEN 1 AND 2147483647),
  provider_status TEXT NOT NULL CHECK (length(provider_status) BETWEEN 1 AND 40),
  normalized_state TEXT NOT NULL CHECK (normalized_state IN ('created','approved','pending','completed','failed','refunded','reversed','canceled')),
  safe_error_code TEXT CHECK (safe_error_code IS NULL OR length(safe_error_code) BETWEEN 1 AND 100),
  paypal_debug_id TEXT CHECK (paypal_debug_id IS NULL OR length(paypal_debug_id) BETWEEN 1 AND 100),
  create_request_digest TEXT NOT NULL CHECK (length(create_request_digest)=64 AND create_request_digest NOT GLOB '*[^0-9a-f]*'),
  create_response_digest TEXT CHECK (create_response_digest IS NULL OR (length(create_response_digest)=64 AND create_response_digest NOT GLOB '*[^0-9a-f]*')),
  capture_request_digest TEXT CHECK (capture_request_digest IS NULL OR (length(capture_request_digest)=64 AND capture_request_digest NOT GLOB '*[^0-9a-f]*')),
  capture_response_digest TEXT CHECK (capture_response_digest IS NULL OR (length(capture_response_digest)=64 AND capture_response_digest NOT GLOB '*[^0-9a-f]*')),
  approved_at TEXT,
  captured_at TEXT,
  pending_at TEXT,
  failed_at TEXT,
  refunded_at TEXT,
  reversed_at TEXT,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (commerce_order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (donation_id) REFERENCES commerce_donations(id) ON DELETE RESTRICT,
  UNIQUE (idempotency_key),
  CHECK ((commerce_order_id IS NOT NULL AND donation_id IS NULL) OR (commerce_order_id IS NULL AND donation_id IS NOT NULL)),
  CHECK ((provider='paypal' AND environment IN ('sandbox','live')) OR (provider='stripe' AND environment IN ('test','live')))
);
CREATE TABLE commerce_paypal_webhook_events (
  provider_event_id TEXT PRIMARY KEY CHECK (length(provider_event_id) BETWEEN 1 AND 80),
  environment TEXT NOT NULL CHECK (environment IN ('sandbox','live','simulator')),
  event_type TEXT NOT NULL CHECK (event_type IN (
    'CHECKOUT.ORDER.APPROVED','CHECKOUT.PAYMENT-APPROVAL.REVERSED',
    'PAYMENT.CAPTURE.PENDING','PAYMENT.CAPTURE.COMPLETED','PAYMENT.CAPTURE.DECLINED',
    'PAYMENT.CAPTURE.REFUNDED','PAYMENT.CAPTURE.REVERSED'
  )),
  provider_order_id TEXT CHECK (provider_order_id IS NULL OR length(provider_order_id) BETWEEN 1 AND 80),
  provider_capture_id TEXT CHECK (provider_capture_id IS NULL OR length(provider_capture_id) BETWEEN 1 AND 80),
  amount_minor INTEGER CHECK (amount_minor IS NULL OR amount_minor BETWEEN 0 AND 2147483647),
  currency_code TEXT CHECK (currency_code IS NULL OR currency_code = 'CAD'),
  merchant_id TEXT CHECK (merchant_id IS NULL OR length(merchant_id) BETWEEN 1 AND 80),
  transmission_id TEXT NOT NULL CHECK (length(transmission_id) BETWEEN 1 AND 80),
  payload_sha256 TEXT NOT NULL CHECK (length(payload_sha256)=64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*'),
  verification_status TEXT NOT NULL CHECK (verification_status IN ('verified','simulator')),
  processing_status TEXT NOT NULL CHECK (processing_status IN ('processed','ignored','unresolved','error')),
  result_code TEXT NOT NULL CHECK (length(result_code) BETWEEN 1 AND 100),
  occurred_at TEXT,
  received_at TEXT NOT NULL,
  processed_at TEXT,
  UNIQUE (environment,transmission_id),
  UNIQUE (environment,payload_sha256)
);
CREATE TABLE IF NOT EXISTS "commerce_operation_jobs" (
  id TEXT PRIMARY KEY CHECK (id GLOB 'coj_*' AND length(id) BETWEEN 40 AND 80),
  job_kind TEXT NOT NULL CHECK (job_kind IN (
    'fulfillment_submit','fulfillment_reconcile','email_send','paypal_order_reconcile',
    'paypal_capture_recover','paypal_pending_reconcile','paypal_webhook_recover',
    'store_payment_complete','donation_payment_complete'
  )),
  event_key TEXT NOT NULL CHECK (length(event_key) BETWEEN 1 AND 180),
  order_id TEXT,
  donation_id TEXT,
  payment_attempt_id TEXT,
  environment TEXT NOT NULL CHECK (environment IN ('sandbox','test','live')),
  payload_digest TEXT NOT NULL CHECK (length(payload_digest)=64 AND payload_digest NOT GLOB '*[^0-9a-f]*'),
  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','leased','retry','action_required','completed','canceled')),
  lease_token TEXT CHECK (lease_token IS NULL OR length(lease_token) BETWEEN 16 AND 120),
  lease_expires_at TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count BETWEEN 0 AND 1000000),
  max_attempts INTEGER NOT NULL DEFAULT 8 CHECK (max_attempts BETWEEN 1 AND 100),
  next_attempt_at TEXT NOT NULL,
  last_error_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(last_error_json) AND json_type(last_error_json)='object' AND length(last_error_json)<=4096),
  completed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES commerce_orders(id) ON DELETE RESTRICT,
  FOREIGN KEY (donation_id) REFERENCES commerce_donations(id) ON DELETE RESTRICT,
  FOREIGN KEY (payment_attempt_id) REFERENCES commerce_payment_attempts(id) ON DELETE RESTRICT,
  UNIQUE (job_kind,event_key),
  CHECK ((state='leased' AND lease_token IS NOT NULL AND lease_expires_at IS NOT NULL) OR (state<>'leased' AND lease_token IS NULL AND lease_expires_at IS NULL))
);
CREATE TABLE IF NOT EXISTS "commerce_provider_diagnostics" (
  id TEXT PRIMARY KEY CHECK (id GLOB 'cpd_*' AND length(id) BETWEEN 40 AND 80),
  provider TEXT NOT NULL CHECK (provider IN ('stripe','paypal','printful','resend')),
  operation_kind TEXT NOT NULL CHECK (length(operation_kind) BETWEEN 1 AND 80),
  http_status INTEGER CHECK (http_status IS NULL OR http_status BETWEEN 100 AND 599),
  provider_code TEXT CHECK (provider_code IS NULL OR length(provider_code) BETWEEN 1 AND 100),
  provider_reason TEXT CHECK (provider_reason IS NULL OR length(provider_reason) BETWEEN 1 AND 300),
  request_id TEXT CHECK (request_id IS NULL OR length(request_id) BETWEEN 1 AND 160),
  payload_digest TEXT CHECK (payload_digest IS NULL OR (length(payload_digest)=64 AND payload_digest NOT GLOB '*[^0-9a-f]*')),
  retryable INTEGER NOT NULL DEFAULT 0 CHECK (retryable IN (0,1)),
  occurred_at TEXT NOT NULL
);
